#!/usr/bin/env python3
"""Writes common-emoji.txt, the emoji of the common emoji font (build.py), from Unicode's emoji list.

Run: python3 vendor/noto-emoji/charset.py packages/pdf-fonts/test/fixtures/emoji-test-17.0.txt

Standard library only. The input is Unicode's emoji-test.txt for the Emoji version the font supports (Unicode License,
https://www.unicode.org/terms_of_use.html), the file packages/pdf-fonts/test/fixtures keeps. The output is checked in; build.py
reads it. The set is the fully-qualified emoji of the groups in GROUPS that are one code point (with the variation selector
the list gives it), and the twelve keycaps: faces, hands and single figures, animals, plants, food, and symbols. A sequence
(a ZWJ sequence, a skin tone, a flag, a tag sequence) and the groups Travel & Places, Activities, Objects and Flags are not in
it; a document with one of those takes the full font.
"""

import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
OUTPUT = HERE / "common-emoji.txt"
GROUPS = ("Smileys & Emotion", "People & Body", "Animals & Nature", "Food & Drink", "Symbols")
VS16 = 0xFE0F
KEYCAP = 0x20E3


def wanted(codes: list) -> bool:
    single = len(codes) == 1 or (len(codes) == 2 and codes[1] == VS16)
    keycap = len(codes) == 3 and codes[1] == VS16 and codes[2] == KEYCAP
    return single or keycap


def main() -> int:
    if len(sys.argv) != 2:
        print(__doc__.splitlines()[2].strip(), file=sys.stderr)
        return 2
    version = ""
    group = ""
    chosen = {}
    for line in Path(sys.argv[1]).read_text(encoding="utf-8").splitlines():
        if line.startswith("# Version:"):
            version = line.split(":", 1)[1].strip()
        elif line.startswith("# group:"):
            group = line.split(":", 1)[1].strip()
        elif line and not line.startswith("#"):
            fields, _, comment = line.partition("#")
            sequence, _, status = fields.partition(";")
            codes = [int(code, 16) for code in sequence.split()]
            if group in GROUPS and status.strip() == "fully-qualified" and wanted(codes):
                chosen.setdefault(group, []).append(" ".join(f"{code:04X}" for code in codes))
    out = [
        "# The emoji of NotoEmoji-Regular-common.woff, one per line as hexadecimal code points, in the order of Unicode's list.",
        f"# Generated by charset.py from Unicode's emoji-test.txt, version {version}; do not edit. How the set is chosen is in README.md.",
        f"# {sum(len(lines) for lines in chosen.values())} emoji.",
    ]
    for name in GROUPS:
        out.append(f"# group: {name}")
        out += chosen.get(name, [])
    OUTPUT.write_text("\n".join(out) + "\n", encoding="utf-8", newline="\n")
    print(f"{OUTPUT.name}: {sum(len(lines) for lines in chosen.values())} emoji (Emoji {version})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
